/* RE-KORD service worker — generated by vite.config.ts (rekordServiceWorker plugin)
 * from src/lib/platform/serviceWorker.template.js. Do not edit dist/sw.js.
 *
 * Only the app shell: index.html and the build's static files. API, audio,
 * covers and admin panel always go to the network (never from the cache): they are
 * the hub's data, and a stale copy would be worse than an error.
 */
const VERSION = "__REKORD_SW_VERSION__";
const PRECACHE = __REKORD_SW_PRECACHE__;
const CACHE = `rekord-shell-${VERSION}`;
const NETWORK_ONLY = [/^\/api(\/|$)/, /^\/media(\/|$)/, /^\/admin(\/|$)/];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll(PRECACHE))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys
            .filter((k) => k.startsWith("rekord-shell-") && k !== CACHE)
            .map((k) => caches.delete(k)),
        ),
      )
      .then(() => self.clients.claim()),
  );
});

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  if (NETWORK_ONLY.some((re) => re.test(url.pathname))) return;
  // Partial (Range) requests don't go through the cache.
  if (req.headers.has("range")) return;

  if (req.mode === "navigate") {
    // Network first: an updated hub serves the new UI right away. Offline,
    // the last cached index.html (the connection indicator does the rest).
    event.respondWith(
      fetch(req)
        .then((res) => {
          if (res.ok) {
            const copy = res.clone();
            caches.open(CACHE).then((c) => c.put("/index.html", copy));
          }
          return res;
        })
        .catch(() =>
          caches.match("/index.html").then((hit) => hit || Response.error()),
        ),
    );
    return;
  }

  // Build files: they have the hash in their name, so the cache never goes stale.
  event.respondWith(
    caches.match(req).then(
      (hit) =>
        hit ||
        fetch(req).then((res) => {
          if (res.ok && url.pathname.startsWith("/assets/")) {
            const copy = res.clone();
            caches.open(CACHE).then((c) => c.put(req, copy));
          }
          return res;
        }),
    ),
  );
});
